package com.muxigame.city;

import java.util.*;
import java.nio.file.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.network.chat.Component;
import net.minecraft.commands.Commands;
import net.minecraft.world.level.storage.LevelResource;
import com.mojang.brigadier.arguments.StringArgumentType;
import com.mojang.brigadier.arguments.IntegerArgumentType;
import net.neoforged.neoforge.event.RegisterCommandsEvent;

/** Normal-operation acceptance run after an explicitly authorized, externally archived fixture reset. */
public final class CityModelLab {
 public static final class Run {
  public UUID city,village;public boolean running,done,continuation,aborted;public long stoppedClock;public String version="";public int targetDays=30,sampleDays=1,speed=30;public Set<UUID> initialDead=new LinkedHashSet<>();public String failure="",startedAt="",endedAt="";
  public long spoiledGrain,spoiledMeat;public long startClock,startGame,lastSample,money,grain,meat,goods,harvest,eaten,meatProduced,meatEaten,supplierInput,initialIssued,initialRetired,jointStart;
  public Set<UUID> people=new LinkedHashSet<>();public List<Map<String,Object>> samples=new ArrayList<>();
 }
 static Run run(MinecraftServer s){return CityTrade.get(s).state.modelRun;}
 static boolean scope(Run r,UUID id){return id.equals(r.city)||id.equals(r.village);}
 static void register(RegisterCommandsEvent event){event.getDispatcher().register(Commands.literal("citymodel").requires(s->s.hasPermission(2)).then(Commands.literal("start").then(Commands.argument("city",StringArgumentType.word()).then(Commands.argument("village",StringArgumentType.word()).executes(ctx->{try{start(ctx.getSource().getServer(),UUID.fromString(StringArgumentType.getString(ctx,"city")),UUID.fromString(StringArgumentType.getString(ctx,"village")));ctx.getSource().sendSuccess(()->Component.literal("新模型100人30日常态实服观察已开始，重置操作必须有独立归档"),false);return 1;}catch(Exception ex){ctx.getSource().sendFailure(Component.literal(ex.getMessage()));return 0;}})))).then(Commands.literal("continue").then(Commands.argument("days",IntegerArgumentType.integer(1,3650)).then(Commands.argument("speed",IntegerArgumentType.integer(1,SimulationClock.MAX_SPEED)).executes(ctx->{try{resume(ctx.getSource().getServer(),IntegerArgumentType.getInteger(ctx,"days"),IntegerArgumentType.getInteger(ctx,"speed"));ctx.getSource().sendSuccess(()->Component.literal("沿原人物资产继续长周期观察，不重置、不补款；全部已启用聚落按全局倍速推进"),false);return 1;}catch(Exception ex){ctx.getSource().sendFailure(Component.literal(ex.getMessage()));return 0;}})))).then(Commands.literal("status").executes(ctx->{if(run(ctx.getSource().getServer()).running)sample(ctx.getSource().getServer());write(ctx.getSource().getServer());var r=run(ctx.getSource().getServer());ctx.getSource().sendSuccess(()->Component.literal("新模型运行="+r.running+"；完成="+r.done+"；"+r.failure),false);return 1;})));}
 static void start(MinecraftServer s,UUID city,UUID village){var t=CityTrade.get(s);var d=RuralSettlement.get(s);var r=run(s);CityEconomy.require(!r.running&&!r.done&&!t.state.run.running&&!t.state.riskRun.running,"已有观察不可覆盖");
  var c=CityData.get(s).require(city);var v=CityData.get(s).require(village);CityEconomy.require(c.name.equals("五倍测试·城市")&&v.name.equals("五倍测试·农村")&&c.works.virtual&&v.works.virtual&&CityCurrency.model(s,city)&&CityCurrency.model(s,village),"仅允许已归档重置的新模型五倍场景");
  CityEconomy.require(!d.state.enabled.contains(city)&&!d.state.enabled.contains(village),"待测场景须暂停");r.city=city;r.village=village;r.people.addAll(c.residents);r.people.addAll(v.residents);CityEconomy.require(r.people.size()==100&&r.people.stream().noneMatch(id->d.state.people.get(id).dead),"新模型基线须有100名初始生者，不得把续测当重置");
  begin(s,r,true);
 }
 static void begin(MinecraftServer s,Run r,boolean fresh){var t=CityTrade.get(s);var d=RuralSettlement.get(s);var c=CityData.get(s).require(r.city);var v=CityData.get(s).require(r.village);r.version="0.10.30";CityMaterialCatalog.ensure(s,c);CityMaterialCatalog.ensure(s,v);r.spoiledGrain=FoodDecay.grain(s);r.spoiledMeat=FoodDecay.meat(s);for(var id:r.people)if(d.state.people.get(id).dead)r.initialDead.add(id);
  r.startClock=d.state.simulationTicks;r.startGame=s.overworld().getGameTime();r.startedAt=java.time.OffsetDateTime.now(java.time.ZoneId.of("Asia/Shanghai")).toString();r.money=t.money(s);r.grain=t.grain(s);r.meat=t.meat(s);r.goods=t.goods(s);r.harvest=t.harvested(s);r.eaten=t.eaten(s);r.meatProduced=t.meatProduced(s);r.meatEaten=t.meatEaten(s);r.supplierInput=t.state.run.supplierInput;r.initialIssued=CityCurrency.issued(s);r.initialRetired=CityCurrency.retired(s);r.jointStart=t.state.jointTransactions;
  for(var town:List.of(c,v)){long shift=r.startClock-town.works.clock;long dayShift=Math.floorDiv(d.state.simulationDay,24000)-Math.floorDiv(town.works.day,24000);long nightShift=Math.floorDiv(d.state.simulationDay-12000,24000)-Math.floorDiv(town.works.day-12000,24000);CityRelief.shift(s,town.id,shift);town.works.clock+=shift;town.works.day=d.state.simulationDay;for(var segment:town.works.queue)segment.day+=shift;town.works.nextDecay+=shift;town.works.nextSegment+=shift;town.works.nextMeal+=shift;for(var b:t.state.businesses.values())if(b.city.equals(town.id)){if(fresh)b.lastIncome=r.startClock;else if(b.lastIncome>=0)b.lastIncome+=shift;if(b.arrive>0)b.arrive+=shift;if(b.nextTrip>0)b.nextTrip+=shift;if(!fresh&&b.departedDay>=0)b.departedDay+=dayShift;}if(!fresh){var market=t.state.towns.get(town.id);if(market.foodStarted)market.foodClock+=shift;for(var price:t.state.towns.get(town.id).prices){if(price.emptySince>=0)price.emptySince+=shift;if(price.richSince>=0)price.richSince+=shift;}for(var id:town.residents){t.state.staffIncomeAt.computeIfPresent(id,(key,time)->time+shift);t.state.shoppingDay.computeIfPresent(id,(key,day)->day+dayShift);var cfg=d.state.hours.get(id);if(cfg!=null){if(cfg.night!=Long.MIN_VALUE)cfg.night+=nightShift;if(cfg.lastWorkedNight!=Long.MIN_VALUE)cfg.lastWorkedNight+=nightShift;}}for(var f:d.state.families.values())if(f.city.equals(town.id)){var home=t.state.households.get(f.id);if(home!=null&&home.day>=0)home.day+=dayShift;}for(var site:d.state.sites.values())if(site.city.equals(town.id)){if(site.blockedSince>0)site.blockedSince+=shift;if(site.vacantSince>0)site.vacantSince+=shift;}}town.works.enabled=true;d.state.enabled.add(town.id);}
  d.state.speed=r.speed;t.linkStaff();r.running=true;r.lastSample=r.startClock;sample(s);write(s);t.setDirty();d.setDirty();CityData.get(s).setDirty();
 }
 static void resume(MinecraftServer s,int days,int speed){var t=CityTrade.get(s);var previous=run(s);CityEconomy.require(previous.done&&!previous.running&&!t.state.run.running&&!t.state.riskRun.running,"只允许完成后的场景续测");CityEconomy.require(days>=1&&days<=3650&&speed>=1&&speed<=SimulationClock.MAX_SPEED,"天数/倍速越界");var d=RuralSettlement.get(s);CityEconomy.require(!d.state.enabled.contains(previous.city)&&!d.state.enabled.contains(previous.village),"场景须保持暂停");try{var file=s.getWorldPath(LevelResource.ROOT).resolve("city_settlements/model099/latest.json");if(Files.exists(file))Files.copy(file,file.resolveSibling("previous.json"),StandardCopyOption.REPLACE_EXISTING);}catch(java.io.IOException ex){throw new IllegalArgumentException("先归档上期报告失败："+ex.getMessage());}var next=new Run();next.city=previous.city;next.village=previous.village;next.people.addAll(previous.people);next.continuation=true;next.targetDays=days;next.sampleDays=Math.max(1,(days+31)/32);next.speed=speed;t.state.modelRun=next;for(UUID id:List.of(next.city,next.village))CityData.get(s).require(id).housing.testSupply=true;begin(s,next,false);}
 static void pause(MinecraftServer s){var r=run(s);for(UUID id:List.of(r.city,r.village)){var c=CityData.get(s).require(id);c.works.enabled=false;c.housing.testSupply=false;RuralSettlement.get(s).state.enabled.remove(id);}CityData.get(s).setDirty();RuralSettlement.get(s).setDirty();}
 static void tick(MinecraftServer s){var r=run(s);if(!r.running)return;long now=RuralSettlement.get(s).state.simulationTicks;if(now-r.lastSample>=r.sampleDays*24000L){r.lastSample=now;sample(s);write(s);}if(r.running&&now-r.startClock>=r.targetDays*24000L){r.running=false;r.done=true;r.endedAt=java.time.OffsetDateTime.now(java.time.ZoneId.of("Asia/Shanghai")).toString();pause(s);sample(s);write(s);}CityTrade.get(s).setDirty();}
 static void sample(MinecraftServer s){var t=CityTrade.get(s);var d=RuralSettlement.get(s);var e=CityEconomy.get(s);var r=run(s);long issued=CityCurrency.issued(s)-r.initialIssued,retired=CityCurrency.retired(s)-r.initialRetired;
  var row=new LinkedHashMap<String,Object>();row.put("days",(d.state.simulationTicks-r.startClock)/24000.0);row.put("gameTick",s.overworld().getGameTime());row.put("money",t.money(s));row.put("issued",issued);row.put("retired",retired);row.put("moneyError",t.money(s)-r.money-issued+retired);row.put("grain",t.grain(s));row.put("grainError",t.grain(s)-r.grain-(t.harvested(s)-r.harvest)+(t.eaten(s)-r.eaten)+FoodDecay.grain(s)-r.spoiledGrain);row.put("spoiledGrain",FoodDecay.grain(s)-r.spoiledGrain);row.put("spoiledMeat",FoodDecay.meat(s)-r.spoiledMeat);row.put("meatError",t.meat(s)-r.meat-(t.meatProduced(s)-r.meatProduced)+(t.meatEaten(s)-r.meatEaten)+FoodDecay.meat(s)-r.spoiledMeat);row.put("goodsError",t.goods(s)-r.goods-(t.state.run.supplierInput-r.supplierInput));
  row.put("living",r.people.stream().map(d.state.people::get).filter(p->!p.dead).count());row.put("newDeaths",r.people.stream().filter(id->!r.initialDead.contains(id)&&d.state.people.get(id).dead).map(id->d.state.people.get(id).name).toList());row.put("deaths",r.people.stream().map(d.state.people::get).filter(p->p.dead).map(p->p.name).toList());row.put("hungry",r.people.stream().map(d.state.people::get).filter(p->!p.dead&&p.hunger()>0).count());row.put("critical",r.people.stream().map(d.state.people::get).filter(p->!p.dead&&p.hunger()==2).count());
  row.put("people",r.people.stream().map(d.state.people::get).map(p->CityEconomy.JSON.fromJson(CityEconomy.JSON.toJson(p),RuralRules.Person.class)).toList());
  row.put("families",d.state.families.values().stream().filter(f->scope(r,f.city)).map(f->{var info=new LinkedHashMap<String,Object>();info.put("id",f.id);info.put("names",f.members.stream().map(id->d.state.people.get(id).name).toList());info.put("cash",t.familyMoney(s,f));info.put("wheat",RuralRules.count(d.stocks(f.id),false));info.put("bread",RuralRules.count(d.stocks(f.id),true));info.put("meat",RuralMeat.total(d.stocks(f.id)));return info;}).toList());
  row.put("businesses",t.state.businesses.values().stream().filter(b->scope(r,b.city)).map(b->CityEconomy.JSON.fromJson(CityEconomy.JSON.toJson(b),CityTrade.Business.class)).toList());
  var accounts=new TreeMap<String,Long>();for(var entry:e.state.accounts.entrySet())if(entry.getKey().startsWith("person:")&&r.people.contains(UUID.fromString(entry.getKey().substring(7)))||List.of(r.city,r.village).stream().anyMatch(id->entry.getKey().equals("city:"+id)||entry.getKey().equals("market:"+id)||entry.getKey().startsWith("works:"+id+":"))||t.state.businesses.values().stream().anyMatch(b->scope(r,b.city)&&b.account.equals(entry.getKey())))accounts.put(entry.getKey(),entry.getValue());row.put("accounts",accounts);
  row.put("currencies",CityEconomy.JSON.fromJson(CityEconomy.JSON.toJson(t.state.currencies),Object.class));row.put("directGrain",t.state.directGrain);row.put("reverseGrain",t.state.reverseGrain);row.put("routeMeat",t.state.routeMeat);row.put("jointTransactions",t.state.jointTransactions-r.jointStart);row.put("jointGrain",t.state.jointGrain);row.put("jointMeat",t.state.jointMeat);
  row.put("cities",List.of(r.city,r.village).stream().map(id->{var c=CityData.get(s).require(id);var info=new LinkedHashMap<String,Object>();info.put("city",id);info.put("name",c.name);var farmPlan=CityMaintenance.get(s).state.cities.get(id);info.put("registeredPlots",farmPlan==null?0:farmPlan.baseline.values().stream().filter(value->value.contains("minecraft:wheat")).count());info.put("emergency",c.works.emergency);info.put("damagedBlocks",c.housing.houses.values().stream().mapToLong(h->h.damaged.size()).sum());info.put("missingWorkpoints",c.housing.houses.values().stream().flatMap(h->h.damaged.stream().map(pos->h.baseline.get(pos))).filter(Objects::nonNull).filter(value->CityBlockRules.workstation(CityMaintenance.decode(value))).count());info.put("relief",t.state.relief.get(id));info.put("resources",new TreeMap<>(c.works.resources));info.put("consumed",new TreeMap<>(c.works.materialsConsumed));info.put("recovered",new TreeMap<>(c.works.recovered));info.put("crafted",new TreeMap<>(c.works.crafted));info.put("market",CityEconomy.JSON.fromJson(CityEconomy.JSON.toJson(c.housing.market),Object.class));var stock=new TreeMap<String,Integer>();for(var h:c.housing.houses.values())h.materials.forEach((key,value)->stock.merge(key,value,Integer::sum));info.put("privateMaterials",stock);info.put("repaired",c.works.repaired);info.put("wages",c.works.wages);info.put("queue",c.works.queue.size());info.put("workClock",c.works.clock);info.put("treasury",e.balance(CityEconomy.treasury(id)));info.put("prices",java.util.stream.IntStream.range(0,4).map(g->t.quote(s,id,g,d.state.simulationTicks)).toArray());return info;}).toList());
  row.put("allBoxesWithinTen",d.state.boxes.values().stream().filter(b->scope(r,b.city)).allMatch(b->b.stock.wheat+b.stock.bread+RuralMeat.total(List.of(b.stock))<=10));r.samples.add(row);if(r.samples.size()>64)r.samples.removeFirst();
  if(((Number)row.get("moneyError")).longValue()!=0||((Number)row.get("grainError")).longValue()!=0||((Number)row.get("meatError")).longValue()!=0||((Number)row.get("goodsError")).longValue()!=0){r.failure="实际收支对账失败，保留现场";r.running=false;pause(s);}
 }
 static void atomic(Path path,String json)throws java.io.IOException{Files.createDirectories(path.getParent());var tmp=path.resolveSibling(path.getFileName()+".tmp");Files.writeString(tmp,json);try{Files.move(tmp,path,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException ex){Files.move(tmp,path,StandardCopyOption.REPLACE_EXISTING);}}
 static void write(MinecraftServer s){try{var dir=s.getWorldPath(LevelResource.ROOT).resolve("city_settlements/model099");var r=run(s);atomic(dir.resolve("latest.json"),CityEconomy.JSON.toJson(r));var summary=new LinkedHashMap<String,Object>();summary.put("kind","actual_joint_server_data_model");summary.put("version",r.version);summary.put("running",r.running);summary.put("done",r.done);summary.put("aborted",r.aborted);summary.put("failure",r.failure);summary.put("targetDays",r.targetDays);summary.put("requestedSpeed",r.speed);summary.put("actualSpeed",RuralSettlement.get(s).state.speed);summary.put("startedAt",r.startedAt);summary.put("endedAt",r.endedAt);summary.put("startGame",r.startGame);summary.put("initialMoney",r.money);summary.put("initialGrain",r.grain);summary.put("initialDeaths",r.initialDead.size());summary.put("latest",r.samples.isEmpty()?null:r.samples.getLast());summary.put("history",r.samples.stream().map(row->{var copy=new LinkedHashMap<>(row);for(String key:List.of("people","families","businesses","accounts","cities","currencies"))copy.remove(key);return copy;}).toList());atomic(dir.resolve("latest-summary.json"),CityEconomy.JSON.toJson(summary));}catch(Exception ex){org.slf4j.LoggerFactory.getLogger("CityModelLab").warn("新模型报告写入失败",ex);}}
}

